def fibonacci(n):
    """Generate the first n numbers in the Fibonacci sequence."""
    sequence = [0, 1]
    while len(sequence) < n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence[:n]


def generate_sequence(formula, n):
    """Generate a sequence of numbers based on a given formula."""
    if formula == "fibonacci":
        return fibonacci(n)
    else:
        raise ValueError(f"Invalid formula. Supported formulas are 'fibonacci'.")


# Example usage
n = 10
print(f"Fibonacci sequence: {generate_sequence('fibonacci', n)}")
